@Component("kYCProfile-handler")
@ProcessingGroup("kYCProfile-processing-group")
public class KYCProfileEventHandler {
	
	// core constructor
	KYCProfileEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateKYCProfileEvent
     */
    @EventHandler
    public void handle( CreateKYCProfileEvent event) {
        entityManager.persist(new KYCProfile(event.getKYCProfileId(), event.getProfileId(), event.getCreatedAt(), event.getCustomer(), event.getDocuments(), event.getScreenings(), event.getAddresses(), event.getStatus(), event.getVerificationLevel()));
    }

    /*
     * @param	event UpdateKYCProfileEvent
     */
    @EventHandler
    public KYCProfile handle( UpdateKYCProfileEvent event) {
    	entityManager.merge(new KYCProfile(event.getKYCProfileId(), event.getProfileId(), event.getCreatedAt(), event.getCustomer(), event.getDocuments(), event.getScreenings(), event.getAddresses(), event.getStatus(), event.getVerificationLevel()));
    }
    
    /*
     * @param	event DeleteKYCProfileEvent
     */
    @EventHandler
    public void on( DeleteKYCProfileEvent event) {
    	KYCProfile entity = new KYCProfile();
   
    	// ------------------------------------------
    	// apply the KYCProfileId
    	// ------------------------------------------
    	entity.setKYCProfileId( event.getKYCProfileId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final KYCProfileRepository kYCProfileEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(KYCProfileEventHandler.class.getName());

}
